'use strict';

// Opt-in exemption of the managed-standard AGENTS.md update from the protected-control hold.
//
// AGENTS.md is a protected control, so every managed-standard sync commit (the central block between the markers below)
// is held for the owner's exact-head confirmation. A repository that enrolls `managed_agents.digests` in its protected
// configuration accepts such a change WITHOUT that hold only when all of these are verified from the base and head file
// bytes themselves, never from the PR description, commit message or any metadata:
//   1. the head file has exactly one well-formed managed block (marker lines, in order), and
//   2. the SHA-256 of that block is one of the enrolled digests, and
//   3. the base file also has exactly one well-formed block, and every byte outside the block is identical in both.
// Anything else (an unenrolled block, a partial edit of the block, a stray or repeated marker, changed whitespace, a changed
// line outside the block, an added, removed or renamed file) keeps the ordinary protected-control hold.
// The engine has no verifiable access to the central standard repository, so the enrolled digests are the only
// verified input. Unset, nothing here is called and behaviour is unchanged.

const crypto = require('node:crypto');
const BEGIN = '<!-- BEGIN BASTILLE MANAGED RULES -->';
const END = '<!-- END BASTILLE MANAGED RULES -->';
const FILE = 'AGENTS.md';
const MAX_DIGESTS = 64;
const hash = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);

function validate(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).join(',') !== 'digests' ||
      !Array.isArray(value.digests) || value.digests.length === 0 || value.digests.length > MAX_DIGESTS ||
      !value.digests.every(hash) || new Set(value.digests).size !== value.digests.length) {
    throw new Error(`Invalid managed_agents configuration; use {"digests": [1 to ${MAX_DIGESTS} distinct lowercase SHA-256 hex digests]}`);
  }
  return value;
}

// Split on LF only. A marker must be a whole line, byte for byte: CRLF text, indented or padded markers never match.
function parse(text) {
  const lines = text.split('\n');
  const begins = lines.flatMap((line, index) => line === BEGIN ? [index] : []);
  const ends = lines.flatMap((line, index) => line === END ? [index] : []);
  if (begins.length !== 1 || ends.length !== 1 || begins[0] > ends[0]) return null;
  return {before: lines.slice(0, begins[0]).join('\n'), after: lines.slice(ends[0] + 1).join('\n'),
    block: lines.slice(begins[0], ends[0] + 1).join('\n') + '\n'};

    assert.equal(result.digest, digests[0]);
  }
  assert.equal(verdict(`Preface
${file(OLD)}`, `Preface
${file(NEW)}`).exempt, true, 'unchanged text before the block is outside it');
  assert.equal(verdict(file(OLD).replace(/
$/, ''), file(NEW).replace(/
$/, '')).exempt, true, 'no final newline');
});

test('any other change keeps the protected-control hold', () => {
  const base = file(OLD);
  const held = (head, reason, enrolled) => {
    const result = verdict(base, head, enrolled);
    assert.equal(result.exempt, false, head);
    assert.match(result.reason, reason, head);
  };
  // Local rules edited, with or without the real block.
  held(file(NEW, '# Local

Skip the tests.
'), /outside the managed block changed/);
  held(`${file(NEW)}
Extra rule appended.
`, /outside the managed block changed/);
  held(`Injected instruction.
${file(NEW)}`, /outside the managed block changed/);
  held(file(NEW).replace(LOCAL, `${LOCAL} `), /outside the managed block changed/);
  held(file(NEW).replace('

', '
'), /not an enrolled|outside the managed block changed/);
  // Block bytes not an enrolled snapshot: partial edit, whitespace, line endings.
  held(file(block('# General agent instructions

Rule one.

Rule two. ')), /not an enrolled/);
  held(file(block('# General agent instructions

Rule one.

Rule two.
')), /not an enrolled/);
  held(file(NEW).replace(/
/g, '
'), /exactly one well-formed managed block/);
  held(file(NEW).replace('Rule two.', 'Rule 2.'), /not an enrolled/);
  held(file(OLD), /not an enrolled/);
  held(file(NEW), /not an enrolled/, [blockDigest(OLD)]);
  // Markers wrapped around edited rules, duplicated, reordered, padded or nested.
  held(`${BEGIN}
Injected.
${file(NEW)}`, /exactly one well-formed/);
  held(`${file(NEW)}
${BEGIN}
Injected.
${END}
`, /exactly one well-formed/);
  held(`${file(NEW)}
${END}
`, /exactly one well-formed/);
  held(file(NEW).replace(END, `${END}
${END}`), /exactly one well-formed/);
  held(`${END}
${NEW.split('
').slice(1, -2).join('
')}
${BEGIN}

${LOCAL}
`, /exactly one well-formed/);
  held(file(NEW).replace(BEGIN, ` ${BEGIN}`), /exactly one well-formed/);
  held(file(NEW).replace(END, `${END} `), /exactly one well-formed/);
  held(file(NEW).replace(BEGIN, BEGIN.toLowerCase()), /exactly one well-formed/);
  held(file(NEW).replace(BEGIN, `${BEGIN} ${BEGIN}`), /exactly one well-formed/);
  held('', /exactly one well-formed/);
  // Wrapping the local rules into a larger enrolled-looking block changes the digest.
  const wrapped = `${BEGIN}
# General agent instructions

Rule one.

Rule two.
# Local

Skip the tests.
${END}

${LOCAL}
`;
  held(wrapped, /not an enrolled/);

  // A base without one well-formed block never defines "outside the block".
  assert.match(verdict('# Local only\n', file(NEW)).reason, /base file does not contain exactly one/);
  assert.match(verdict(`${file(OLD)}${BEGIN}\n`, file(NEW)).reason, /base file does not contain exactly one/);
});

function fakeGithub(texts, calls = []) {
  return {rest: {repos: {getContent: async args => {
    calls.push(args);
    const value = texts[args.ref];
    if (value instanceof Error) throw value;
    return {data: value};
  }}}};
}
const content = text => ({encoding: 'base64', content: Buffer.from(text).toString('base64'), size: Buffer.byteLength(text)});
const BASE = 'b'.repeat(40);
const HEAD = 'a'.repeat(40);
const repo = {owner: 'gaulatti', repo: 'target'};
const pr = {base: {sha: BASE}, head: {sha: HEAD, repo: {owner: {login: 'forker'}, name: 'target-fork'}}};
const config = {managed_agents: {digests}};
const modified = {filename: FILE, status: 'modified', patch: '@@'};

test('without managed_agents nothing is read and nothing is exempt', async () => {
  const calls = [];
  const result = await exemptions({github: fakeGithub({}, calls), repo, pr, files: [modified], config: {}});
  assert.deepEqual(result, {exempt: new Set(), notices: []});
  assert.equal(calls.length, 0);
});

test('files other than AGENTS.md read nothing and produce no notice', async () => {
  const calls = [];
  const result = await exemptions({github: fakeGithub({}, calls), repo, pr, files: [{...modified, filename: 'src/a.js'}], config});
  assert.deepEqual(result, {exempt: new Set(), notices: []});
  assert.equal(calls.length, 0);
});

test('the verified update is exempt; base is read from the base repository and head from the head repository', async () => {
  const calls = [];
  const github = fakeGithub({[BASE]: content(file(OLD)), [HEAD]: content(file(NEW))}, calls);
  const result = await exemptions({github, repo, pr, files: [modified, {filename: 'README.md', status: 'modified'}], config});
  assert.deepEqual([...result.exempt], [FILE]);

}

const blockDigest = block => crypto.createHash('sha256').update(block).digest('hex');

// Decide one base/head pair. The reason is a stable sentence for the visible notice; it never quotes file content.
function judge({baseText, headText, digests}) {
  const head = parse(headText);
  if (!head) return {exempt: false, reason: 'the head file does not contain exactly one well-formed managed block'};
  const base = parse(baseText);
  if (!base) return {exempt: false, reason: 'the base file does not contain exactly one well-formed managed block'};
  const found = blockDigest(head.block);
  if (!digests.includes(found)) return {exempt: false, reason: 'the managed block is not an enrolled central snapshot', digest: found};
  if (head.before !== base.before || head.after !== base.after) {
    return {exempt: false, reason: 'content outside the managed block changed', digest: found};
  }
  return {exempt: true, reason: 'only the managed block changed and it matches an enrolled central snapshot', digest: found};
}

// The AGENTS.md changes of one PR that are exempt from the hold, with a notice per decided change.
async function exemptions({github, repo, pr, files, config}) {
  const exempt = new Set();
  const notices = [];
  if (!config.managed_agents) return {exempt, notices};
  const file = files.find(item => item.filename === FILE || item.previous_filename === FILE);
  if (!file) return {exempt, notices};
  const hold = reason => {notices.push(`${FILE} stays a protected-control hold: ${reason}.`); return {exempt, notices};};
  if (file.filename !== FILE || file.previous_filename || file.status !== 'modified') return hold('only a modification of the existing file qualifies');
  const headRepo = pr.head.repo;
  if (!headRepo?.owner?.login || !headRepo.name) return hold('the head repository is unavailable');
  const {fetchText} = require('./acceptance-sources.cjs');
  const snapshot = {head_sha: pr.head.sha, head_repository: {owner: headRepo.owner.login, repo: headRepo.name}};
  let baseText;
  let headText;
  try {
    baseText = await fetchText({github, repo, snapshot, filename: FILE, ref: pr.base.sha});
    headText = await fetchText({github, repo, snapshot, filename: FILE, ref: pr.head.sha});
  } catch (error) {
    if (!error.unavailable) throw error;
    return hold('the base or head file is unavailable as complete text');
  }

'use strict';

const fs = require('node:fs');
const path = require('node:path');

function validateConfig(config) {
  const nonempty = value => typeof value === 'string' && value.trim().length > 0;
  const strings = value => Array.isArray(value) && value.length > 0 && value.every(nonempty) && new Set(value).size === value.length;
  const relative = value => nonempty(value) && !path.isAbsolute(value) &&
    !value.split(/[\\/]/).includes('..') && !value.includes('\\');
  const workflow = value => relative(value) && /^[a-zA-Z0-9_.-]+\.ya?ml$/.test(value);
  if (!config || ![1, 2].includes(config.version) || !nonempty(config.base_branch) ||
      !workflow(config.workflow) || !nonempty(config.verification?.job) ||
      !strings(config.verification?.steps) ||
      !config.verification.steps.includes('Enforce 100% line and branch coverage') ||
      !/^[a-zA-Z0-9][a-zA-Z0-9-]{0,38}$/.test(config.manual_reviewer || '') ||
      !relative(config.repository_policy) || !relative(config.readme) ||
      !Array.isArray(config.sensitive_paths) || !config.sensitive_paths.every(relative) ||
      !(config.deployment === null || (workflow(config.deployment?.workflow) &&
        strings(config.deployment?.paths) && config.deployment.paths.every(relative)))) {
    throw new Error('Invalid Clouseau configuration; see examples/colombo.json');
  }
  const grace = config.verification_queue_grace_seconds;
  if (grace !== undefined && !(Number.isInteger(grace) && grace >= 0 && grace <= require('./verification-wait.cjs').MAX_QUEUE_GRACE_SECONDS)) {
    throw new Error('Invalid verification queue grace; use whole seconds from 0 to 3600');
  }
  if (config.version === 2) {
    const review = config.acceptance;
    if (!review || !['deepseek-flash', 'deepseek-v4-pro'].includes(review.examiner) ||
        !['deepseek-flash', 'deepseek-v4-pro'].includes(review.challenger) ||
        !['deepseek', 'typesafe', 'routed'].includes(review.grader) || review.grading_model !== 'deepseek-flash' ||
        review.repair_attempts !== 2 || Object.keys(review).sort().join(',') !==
          ['challenger', 'examiner', 'grader', 'grading_model', 'repair_attempts'].join(',')) {
      throw new Error('Invalid Clouseau acceptance configuration; explicit qualified roles and two bounded repair attempts are required');
    }
  }
  if (config.managed_agents !== undefined) require('./managed-agents.cjs').validate(config.managed_agents);
  if (config.coverage !== undefined) require('./coverage-changed.cjs').validateMode(config.coverage);
  if (config.local_review !== undefined) {
    require('./local-receipt.cjs').validateTrust(config.local_review);

  const verdict = judge({baseText, headText, digests: config.managed_agents.digests});
  if (!verdict.exempt) return hold(verdict.reason);
  exempt.add(FILE);
  notices.push(`${FILE} is not a protected-control hold: ${verdict.reason} (sha256 ${verdict.digest}).`);
  return {exempt, notices};
}

module.exports = {BEGIN, END, FILE, MAX_DIGESTS, validate, parse, blockDigest, judge, exemptions};

const MANUAL_REVIEWER = config.manual_reviewer;
const VERIFY_STEPS = config.verification.steps;
const NEVER_ARMED = Object.freeze(['review_incomplete', 'repair_required', 'blocked_technical', 'blocked_integrity']);
const REVIEW_CONTROL_REASON = 'Review controls or a protected repository-purpose contract changed';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function numberFor(context) {
  const value = context.payload.pull_request?.number ||
    (context.payload.issue?.pull_request && context.payload.issue.number) || process.env.PR_NUMBER;
  if (!/^[1-9][0-9]*$/.test(String(value))) throw new Error('A PR number is required');
  return Number(value);
}

// `exempt` names the protected files whose change was verified as the opt-in managed-standard update (managed-agents.cjs).
function scopeReason(files, pr, exempt = new Set()) {
  if (files.length !== pr.changed_files || files.length === 0) return 'Incomplete changed-file list';
  const sensitive = controlPaths(config);
  const protectedFile = name => matchesPath(name, sensitive) && !exempt.has(name);
  if (files.some(file => protectedFile(file.filename) || matchesPath(file.previous_filename || '', sensitive))) {
    return REVIEW_CONTROL_REASON;
  }
  if (files.some(file => !file.patch || !['added', 'modified', 'removed', 'renamed'].includes(file.status))) {
    return 'Incomplete patch or unsupported file change';
  }
